import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); c.Initialized(); }
    function testFuzz_property(uint256 lockTime, address caller, uint128 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        // Ensure sender has enough ETH
        vm.deal(caller, amount);
        // Record pre-state
        (uint preUnlock, uint preBal) = c.Acc(caller);
        uint preContractBalance = address(c).balance;
        // Execute Put
        vm.prank(caller);
        c.Put{value: amount}(lockTime);
        // Observe post-state
        (uint postUnlock, uint postBal) = c.Acc(caller);
        uint postContractBalance = address(c).balance;
        // Invariant: sum of caller's account balance and contract balance must have increased by at least msg.value (>= amount) when compared to the pre-state.
        // Because no other function is called, the ETH received is exactly msg.value, and the balance mapping tracking should be consistent.
        // Alternatively: preBal + preContractBalance + amount <= postBal + postContractBalance
        assertTrue(preBal + preContractBalance + amount <= postBal + postContractBalance);
    }
}

