pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();
    }

    function testFuzz_property(uint256 amt, uint256 lockTime, uint128 collectAmt) public {
        // Bound amt to avoid overflow and be strictly positive to trigger the bug
        vm.assume(amt > 0 && amt < type(uint128).max);
        // Bound lockTime to a reasonable future range
        lockTime = bound(lockTime, 0, 365 days);
        // Bound collectAmt to be at most the deposited amount
        collectAmt = uint128(bound(uint256(collectAmt), 0, amt));

        address actor = address(0x100);
        vm.deal(actor, amt);
        vm.prank(actor);

        // Record initial ETH balance of actor
        uint256 balBefore = actor.balance;

        // Put ETH into the contract
        c.Put{value: amt}(lockTime);

        // Now warp to after unlock time so Collect can proceed
        vm.warp(block.timestamp + lockTime + 1);

        // Try to Collect the chosen amount
        bool ok = true;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // The invariant: if Collect succeeds (ok == true), the actor's ETH balance must be balBefore - amt + collectAmt.
        // That is, the actor's net ETH change = -(amt) + collectAmt (paid amt ETH, got collectAmt back).
        // The buggy version decreases the internal balance on Put, so the Collect may revert or return wrong ETH.
        // If it doesn't revert, the ETH transfer should still be exactly collectAmt.
        // But a stricter invariant: the actor's ETH balance after a successful Collect MUST be exactly balBefore - amt + collectAmt.
        if (ok) {
            assertEq(actor.balance, balBefore - amt + collectAmt);
        }
    }
}

