pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint64 unlockDelay, uint64 warpTime) public {
        // Bound inputs to reasonable, admissible ranges
        putAmount = bound(putAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);
        unlockDelay = uint64(bound(unlockDelay, 1, type(uint64).max - 10));
        warpTime = uint64(bound(warpTime, 0, unlockDelay - 1));

        // Setup: initialize contract, set MinSum to 0, and setup a user with some ether
        address user = address(0x1234);
        vm.deal(user, putAmount);
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // User puts ether with a future unlock time
        vm.prank(user);
        c.Put{value: putAmount}(uint256(unlockDelay));

        // Warp to a time strictly before the unlock time
        uint256 before = block.timestamp + uint256(warpTime);
        vm.warp(before);

        // Ensure we are still before unlock time
        (uint256 unlockTime, uint256 balance) = c.Acc(user);
        assertTrue(block.timestamp < unlockTime, "setup: must warp before unlock");

        // Collect amount must not exceed balance
        vm.assume(collectAmount <= balance);

        // Attempt to collect
        vm.prank(user);
        try c.Collect(collectAmount) {
            // Collect succeeded; the reference should never succeed here
            (, uint256 afterBalance) = c.Acc(user);
            assertTrue(afterBalance == balance - collectAmount, "Collect succeeded meaning withdrawal happened");
        } catch {
            // Collect reverted; that's fine for the reference, but the bug would succeed
            assertTrue(true);
        }
    }
}

