        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        // Assert: if Collect succeeded (ok == true), then the current block.timestamp MUST be > unlockTime
        // The reference satisfies this for all inputs, but the buggy contract breaks it when warpTime <= unlockTime
        assertTrue(!ok || block.timestamp > unlockTimeBefore);
    }
}

